/* xlat11_reused.h - HAND-WRITTEN, NOT GENERATED. The gfx10.3 addresses gfx11 REUSES for a different register.
 *
 * WHY THIS FILE EXISTS AND WHY IT IS NOT IN xlat11_tables.h. That file carries the banner "GENERATED by
 * src/xlat11/gen/gen_tables.py - do not edit. Regenerate instead.", and its classifier is NAME-driven: a gfx10.3
 * register whose NAME is absent from gfx11.json is classed ABSENT and its write is DROPPED. That is right for a
 * register gfx11 deleted. It is WRONG for an address gfx11 REUSED, because dropping the write leaves the gfx11
 * register that now lives at that address holding whatever its context slot last held. This tree does not
 * translate CLEAR_STATE (xlat11.c refuses the CLEAR_STATE packet as a memloaded stub), so a dropped reused
 * write cannot rely on a later clear to reinitialise the slot. xlat11.c's lookup() consults these rows FIRST,
 * so they supersede the generated row for the same address whatever the generator later says. tests/test_xlat11.c
 * asserts BOTH halves: that the override wins, and that the generated row is still the ABSENT one it supersedes.
 *
 * THE GFX11 REUSE: the DCC control registers became FDCC control registers at the same MMIO addresses.
 *
 *   0x28424  gfx10.3 CB_DCC_CONTROL             -> gfx11 CB_FDCC_CONTROL
 *   0x28c78  gfx10.3 CB_COLOR0_DCC_CONTROL      -> gfx11 CB_COLOR0_FDCC_CONTROL
 *   0x28cb4  gfx10.3 CB_COLOR1_DCC_CONTROL      -> gfx11 CB_COLOR1_FDCC_CONTROL
 *   0x28cf0  gfx10.3 CB_COLOR2_DCC_CONTROL      -> gfx11 CB_COLOR2_FDCC_CONTROL
 *   0x28d2c  gfx10.3 CB_COLOR3_DCC_CONTROL      -> gfx11 CB_COLOR3_FDCC_CONTROL
 *   0x28d68  gfx10.3 CB_COLOR4_DCC_CONTROL      -> gfx11 CB_COLOR4_FDCC_CONTROL
 *   0x28da4  gfx10.3 CB_COLOR5_DCC_CONTROL      -> gfx11 CB_COLOR5_FDCC_CONTROL
 *   0x28de0  gfx10.3 CB_COLOR6_DCC_CONTROL      -> gfx11 CB_COLOR6_FDCC_CONTROL
 *   0x28e1c  gfx10.3 CB_COLOR7_DCC_CONTROL      -> gfx11 CB_COLOR7_FDCC_CONTROL
 *
 * PROVENANCE (every number CONFIRMED against the archived sources):
 *   - gfx103.json register_mappings: CB_DCC_CONTROL at 0x28424, CB_COLOR{0..7}_DCC_CONTROL at
 *     0x28c78/0x28cb4/0x28cf0/0x28d2c/0x28d68/0x28da4/0x28de0/0x28e1c.
 *   - gfx11.json register_mappings: CB_FDCC_CONTROL / CB_COLOR{0..7}_FDCC_CONTROL at the SAME addresses; the
 *     NAME "CB_DCC_CONTROL" and "CB_COLORn_DCC_CONTROL" are absent from gfx11.json (hence the generated rows are
 *     ABSENT).
 *   - gc_10_3_0_offset.h / gc_11_0_0_offset.h name the same addresses (cross-checked by gen_tables.py).
 *
 * THE VALUE MAPPING uses the generator's own documented repack rule, applied by hand because these rows are
 * NOT in the generated table: every field whose NAME both sides carry is copied from its gfx10.3 bit range to
 * its gfx11 bit range; gfx10.3-only fields are dropped; gfx11-only fields are left 0. The two families:
 *
 *   CB_DCC_CONTROL -> CB_FDCC_CONTROL: shared DISABLE_CONSTANT_ENCODE_AC01/_SINGLE/_REG [8..10],
 *     DISABLE_ELIMFC_SKIP_OF_AC01/_SINGLE [12..13], ENABLE_ELIMFC_SKIP_OF_REG [14]; all at unchanged bits.
 *     gfx10.3-only OVERWRITE_COMBINER_DISABLE [0] and OVERWRITE_COMBINER_WATERMARK [2:6] are dropped.
 *
 *   CB_COLORn_DCC_CONTROL -> CB_COLORn_FDCC_CONTROL: shared MAX_UNCOMPRESSED_BLOCK_SIZE [2:3],
 *     MIN_COMPRESSED_BLOCK_SIZE [4], MAX_COMPRESSED_BLOCK_SIZE [5:6], COLOR_TRANSFORM [7:8],
 *     INDEPENDENT_64B_BLOCKS [9], DISABLE_CONSTANT_ENCODE_REG [18], ENABLE_CONSTANT_ENCODE_REG_WRITE [19],
 *     SKIP_LOW_COMP_RATIO [21]; INDEPENDENT_128B_BLOCKS MOVES [20]->[10]; DCC_COMPRESS_DISABLE MOVES [22]->[23].
 *     gfx10.3-only OVERWRITE_COMBINER_DISABLE [0], KEY_CLEAR_ENABLE [1], LOSSY_RGB_PRECISION [10:13] and
 *     LOSSY_ALPHA_PRECISION [14:17] are dropped.
 *
 * The semantic adequacy of DCC->FDCC by-name relabelling is a STAGE-3 review item (full gfx10.3 coverage and
 * target-machine validation), not a stage-1 claim.
 */
#ifndef XLAT11_REUSED_H
#define XLAT11_REUSED_H

#include <stdint.h>
#include "xlat11.h"
#include "xlat11_tables.h"

/* CB_DCC_CONTROL -> CB_FDCC_CONTROL: the six shared fields, unchanged bits. */
static uint32_t xlat11_reuse_fdcc_global(uint32_t v)
{
    uint32_t o = 0u;
    o |= ((v >>  8) & 1u) <<  8;   /* DISABLE_CONSTANT_ENCODE_AC01 */
    o |= ((v >>  9) & 1u) <<  9;   /* DISABLE_CONSTANT_ENCODE_SINGLE */
    o |= ((v >> 10) & 1u) << 10;   /* DISABLE_CONSTANT_ENCODE_REG */
    o |= ((v >> 12) & 1u) << 12;   /* DISABLE_ELIMFC_SKIP_OF_AC01 */
    o |= ((v >> 13) & 1u) << 13;   /* DISABLE_ELIMFC_SKIP_OF_SINGLE */
    o |= ((v >> 14) & 1u) << 14;   /* ENABLE_ELIMFC_SKIP_OF_REG */
    return o;
}

/* CB_COLORn_DCC_CONTROL -> CB_COLORn_FDCC_CONTROL: shared fields, with the two moves. */
static uint32_t xlat11_reuse_fdcc_color(uint32_t v)
{
    uint32_t o = 0u;
    o |= ((v >>  2) & 0x3u) <<  2;   /* MAX_UNCOMPRESSED_BLOCK_SIZE */
    o |= ((v >>  4) & 0x1u) <<  4;   /* MIN_COMPRESSED_BLOCK_SIZE */
    o |= ((v >>  5) & 0x3u) <<  5;   /* MAX_COMPRESSED_BLOCK_SIZE */
    o |= ((v >>  7) & 0x3u) <<  7;   /* COLOR_TRANSFORM */
    o |= ((v >>  9) & 0x1u) <<  9;   /* INDEPENDENT_64B_BLOCKS */
    o |= ((v >> 20) & 0x1u) << 10;   /* INDEPENDENT_128B_BLOCKS [20]->[10] */
    o |= ((v >> 18) & 0x1u) << 18;   /* DISABLE_CONSTANT_ENCODE_REG */
    o |= ((v >> 19) & 0x1u) << 19;   /* ENABLE_CONSTANT_ENCODE_REG_WRITE */
    o |= ((v >> 21) & 0x1u) << 21;   /* SKIP_LOW_COMP_RATIO */
    o |= ((v >> 22) & 0x1u) << 23;   /* DCC_COMPRESS_DISABLE [22]->[23] */
    return o;
}

static const Xlat11Entry kXlat11Reused[] = {
    { 0x28424u, 0x28424u, xlat11_reuse_fdcc_global, XLAT11_CLS_REUSED,
      "CB_DCC_CONTROL -> gfx11 CB_FDCC_CONTROL",
      "gfx11 reuses this address for CB_FDCC_CONTROL; shared fields copied by name" },
    { 0x28c78u, 0x28c78u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR0_DCC_CONTROL -> gfx11 CB_COLOR0_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR0_FDCC_CONTROL; shared fields copied by name" },
    { 0x28cb4u, 0x28cb4u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR1_DCC_CONTROL -> gfx11 CB_COLOR1_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR1_FDCC_CONTROL; shared fields copied by name" },
    { 0x28cf0u, 0x28cf0u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR2_DCC_CONTROL -> gfx11 CB_COLOR2_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR2_FDCC_CONTROL; shared fields copied by name" },
    { 0x28d2cu, 0x28d2cu, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR3_DCC_CONTROL -> gfx11 CB_COLOR3_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR3_FDCC_CONTROL; shared fields copied by name" },
    { 0x28d68u, 0x28d68u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR4_DCC_CONTROL -> gfx11 CB_COLOR4_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR4_FDCC_CONTROL; shared fields copied by name" },
    { 0x28da4u, 0x28da4u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR5_DCC_CONTROL -> gfx11 CB_COLOR5_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR5_FDCC_CONTROL; shared fields copied by name" },
    { 0x28de0u, 0x28de0u, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR6_DCC_CONTROL -> gfx11 CB_COLOR6_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR6_FDCC_CONTROL; shared fields copied by name" },
    { 0x28e1cu, 0x28e1cu, xlat11_reuse_fdcc_color, XLAT11_CLS_REUSED,
      "CB_COLOR7_DCC_CONTROL -> gfx11 CB_COLOR7_FDCC_CONTROL",
      "gfx11 reuses this address for CB_COLOR7_FDCC_CONTROL; shared fields copied by name" },
};
#define XLAT11_REUSED_LEN ((uint32_t)(sizeof(kXlat11Reused) / sizeof(kXlat11Reused[0])))

/* The override for `g10`, or 0. Linear over the hand-written rows - deliberately not a binary search, because
 * the array's order must not become load-bearing. */
static const Xlat11Entry *xlat11_reused_lookup(uint32_t g10)
{
    for (uint32_t i = 0; i < XLAT11_REUSED_LEN; i++)
        if (kXlat11Reused[i].g10 == g10) return &kXlat11Reused[i];
    return 0;
}

#endif /* XLAT11_REUSED_H */
